import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import api from '../../utils/api';

function Countdown({ expiresAt }) {
  const calc = () => {
    const diff = new Date(expiresAt) - new Date();
    if (diff <= 0) return '00:00';
    const m = Math.floor(diff / 60000);
    const s = Math.floor((diff % 60000) / 1000);
    return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
  };
  const [time, setTime] = useState(calc());
  useEffect(() => {
    const t = setInterval(() => setTime(calc()), 1000);
    return () => clearInterval(t);
  }, [expiresAt]);
  return <span className="text-orange-500 font-bold text-sm">⏱ {time} left</span>;
}

export default function FlashSalesPage() {
  const navigate = useNavigate();
  const [sales, setSales] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState(false);
  const [selectedSale, setSelectedSale] = useState(null);
  const [address, setAddress] = useState('');
  const [buying, setBuying] = useState(false);

  const load = useCallback(async () => {
    try {
      const res = await api.get('/features/flash-sales');
      setSales(res.data);
    } catch (_) {}
    setLoading(false);
  }, []);

  useEffect(() => { 
    load(); 
    const t = setInterval(load, 30000); 
    return () => clearInterval(t); 
  }, [load]);

  const openBuy = (sale) => { setSelectedSale(sale); setModal(true); };

  const handleBuy = async () => {
    if (!address.trim()) return toast.error('Enter delivery address');
    setBuying(true);
    try {
      const res = await api.post(`/features/flash-sales/${selectedSale.restaurantId}/${selectedSale._id}/buy`, { address });
      setModal(false);
      toast.success(res.data.message);
      navigate(`/track/${res.data.order._id}`);
    } catch (e) {
      toast.error(e.response?.data?.message || 'Failed to buy');
    } finally { setBuying(false); }
  };

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-gray-900">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-orange-500"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-900 text-white">
      <div className="bg-gray-800 p-8 text-center border-b border-gray-700">
        <div className="text-5xl mb-4">♻️</div>
        <h1 className="text-2xl font-extrabold text-green-500 mb-2">Zero-Waste Flash Sales</h1>
        <p className="text-gray-400 text-sm max-w-md mx-auto">
          Grab quality food at 50–70% off before it goes to waste
        </p>
      </div>

      <div className="max-w-3xl mx-auto p-4 py-8">
        {sales.length === 0 ? (
          <div className="flex flex-col items-center justify-center p-12 text-center bg-gray-800 rounded-2xl border border-gray-700 mt-8">
            <div className="text-6xl mb-4">🕐</div>
            <h2 className="text-xl font-bold text-white mb-2">No active flash sales right now</h2>
            <p className="text-gray-400 text-sm max-w-sm">
              Check back around lunch or closing time — restaurants post deals to clear their fresh inventory!
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {sales.map(item => {
              const pct = Math.round((1 - item.salePrice / item.originalPrice) * 100);
              return (
                <div key={item._id} className="bg-gray-800 rounded-2xl p-6 border border-gray-700 hover:border-gray-600 transition shadow-lg flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                  <div className="flex items-start flex-1 w-full gap-4">
                    <div className="text-5xl shrink-0">{item.emoji || '♻️'}</div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start">
                        <div>
                          <h3 className="text-lg font-bold text-white">{item.title}</h3>
                          <p className="text-sm text-gray-400 mt-1">{item.restaurantEmoji} {item.restaurantName}</p>
                        </div>
                        <div className="bg-green-500 text-white text-xs font-bold px-2 py-1 rounded-lg ml-2">
                          -{pct}%
                        </div>
                      </div>
                      {item.description && <p className="text-sm text-gray-400 mt-2">{item.description}</p>}
                    </div>
                  </div>

                  <div className="flex items-center justify-between w-full md:w-auto md:flex-col md:items-end gap-2 shrink-0 border-t border-gray-700 md:border-t-0 pt-4 md:pt-0">
                    <div className="flex md:flex-col items-center md:items-end gap-3 md:gap-0">
                      <div>
                        <span className="text-2xl font-extrabold text-green-400 mr-2 border-green-500">₹{item.salePrice}</span>
                        <span className="text-sm text-gray-500 line-through">₹{item.originalPrice}</span>
                      </div>
                      <div className="flex flex-col items-start md:items-end md:mt-2">
                        <Countdown expiresAt={item.expiresAt} />
                        <span className="text-xs text-gray-500 mt-1">{item.remaining} left</span>
                      </div>
                    </div>
                    <button 
                      onClick={() => openBuy(item)}
                      className="bg-green-500 hover:bg-green-600 text-white font-bold py-2 px-6 rounded-xl transition shadow"
                    >
                      Grab It!
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {modal && (
        <div className="fixed inset-0 bg-black/70 flex items-end sm:items-center justify-center z-50 p-0 sm:p-4 transition-all">
          <div className="bg-gray-800 w-full sm:max-w-md p-6 sm:rounded-2xl rounded-t-3xl border border-gray-700 shadow-2xl relative animate-slide-up sm:animate-none">
            <h3 className="text-xl font-extrabold text-white text-center mb-4">♻️ Confirm Flash Sale</h3>
            {selectedSale && (
              <div className="bg-gray-900 border border-gray-700 rounded-xl p-4 mb-6">
                <p className="text-md text-white text-center font-medium mb-2">{selectedSale.title}</p>
                <p className="text-sm text-green-400 font-bold text-center">₹{selectedSale.salePrice} + ₹40 delivery = ₹{selectedSale.salePrice + 40}</p>
              </div>
            )}
            <textarea
              className="w-full bg-gray-900 border border-gray-700 rounded-xl p-4 text-white placeholder-gray-500 mb-6 h-28 focus:outline-none focus:border-green-500 transition resize-none"
              placeholder="Delivery address"
              value={address}
              onChange={(e) => setAddress(e.target.value)}
            />
            <div className="flex gap-3">
              <button 
                onClick={() => setModal(false)}
                className="flex-1 py-3 px-4 rounded-xl border border-gray-600 text-gray-400 font-bold hover:bg-gray-700 transition"
              >
                Cancel
              </button>
              <button 
                onClick={handleBuy} disabled={buying}
                className="flex-[2] py-3 px-4 rounded-xl bg-green-500 hover:bg-green-600 text-white font-bold transition shadow-lg flex items-center justify-center"
              >
                {buying ? <div className="animate-spin rounded-full h-5 w-5 border-t-2 border-white"></div> : 'Place Order'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
